const crypto = require('crypto');

// Secrets come from n8n Variables (Cloud: Overview > Variables) or, when self-hosting,
// from environment variables (N8N_BLOCK_ENV_ACCESS_IN_NODE=false). Never hard-coded.
function setting(name, { optional = false } = {}) {
  try { if ($vars && $vars[name]) return $vars[name]; } catch (e) {}
  try { if ($env && $env[name]) return $env[name]; } catch (e) {}
  if (optional) return undefined;
  throw new Error(`${name} is not set. Add it as an n8n Variable (Cloud) or environment variable (self-hosted).`);
}

// Signs a call back into LendLoop: sha256=HMAC(secret, `${timestamp}.${body}`)
function signedCall(path, payload) {
  const body = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'sha256=' + crypto
    .createHmac('sha256', setting('LENDLOOP_CALLBACK_SECRET'))
    .update(`${timestamp}.${body}`)
    .digest('hex');
  const base = setting('LENDLOOP_CONVEX_SITE_URL').replace(/\/$/, '');
  return { url: base + path, body, timestamp, signature };
}

function errorText(e) {
  if (!e) return 'unknown error';
  if (typeof e === 'string') return e;
  return e.message || e.description || JSON.stringify(e).slice(0, 300);
}

// Error Trigger payload: { execution: { id, url, error, lastNodeExecuted }, workflow: { id, name } }
// (or { trigger: { error } } when the trigger itself failed).
const d = $input.first().json;
const err = d.execution?.error || d.trigger?.error;
return [{ json: signedCall('/n8n/failures', {
  workflow: d.workflow?.name || 'Unknown workflow',
  executionId: d.execution?.id != null ? String(d.execution.id) : undefined,
  node: d.execution?.lastNodeExecuted || undefined,
  message: errorText(err).slice(0, 500),
}) }];
